@testable import WisqRemote

/// Streams produced by SPICE's own QUIC encoder.
///
/// Generated by `scripts/spice-quic-fixtures/qgen.c`, which links `quic.c` —
/// the reference implementation — and compresses images built from flat bands,
/// a gradient and pseudo-random noise, so the adaptive model meets runs, smooth
/// prediction and surprises in one image. Every stream here was then read back
/// through the reference *decoder* (`qdec.c`), and `decoded` is what that
/// produced.
///
/// This is the difference between checking a decoder against the codec and
/// checking it against a reading of the codec. QUIC has no second
/// implementation to disagree with, so the encoder it shipped with is the only
/// honest authority available.
///
/// Note on `rgb32`: the fourth byte of a pixel is never transmitted, so the
/// reference decoder writes zero there. `decoded` records that, rather than
/// the byte the original happened to hold.
enum SpiceQUICFixtures {
    struct Case {
        let name: String
        let note: String
        let type: SpiceQUIC.ImageType
        let width: Int
        let height: Int
        /// The compressed stream, header included.
        let stream: String
        /// What the reference decoder produced from it.
        let decoded: String
    }

    static func bytes(_ hex: String) -> [UInt8] {
        let digits = hex.filter { !$0.isWhitespace }
        var out: [UInt8] = []
        out.reserveCapacity(digits.count / 2)
        var index = digits.startIndex
        while index < digits.endIndex {
            let next = digits.index(index, offsetBy: 2)
            out.append(UInt8(digits[index..<next], radix: 16) ?? 0)
            index = next
        }
        return out
    }

